    ["Player"] = "Spieler",
    ["Player marker halo"] = "Ring um den Spielerpfeil",
    ["Please write in the comments on WalkMap's CurseForge page. A screenshot or the Debug report (Settings > Controller & help) helps a lot."] = "Bitte schreib in die Kommentare auf WalkMaps CurseForge-Seite. Ein Screenshot oder der Debug-Bericht (Einstellungen > Controller & Hilfe) hilft sehr.",
