    ["Write quest titles beside the game markers."] = "Questtitel neben den Markierungen des Spiels anzeigen.",
    ["X takes control of the map: D-pad pans, LB/RB zooms, Y steps through the markers around the crosshair, A focuses the quest of a quest marker and otherwise sets a waypoint (on the selected marker or at the crosshair), X or B returns."] = "X übernimmt die Karte: Steuerkreuz verschiebt, LB/RB zoomt, Y geht durch die Markierungen um das Fadenkreuz, A fokussiert die Quest einer Questmarkierung und setzt sonst einen Wegpunkt (auf der gewählten Markierung oder am Fadenkreuz), X oder B kehrt zurück.",
    ["X: pan map. Use the game's focus button for skills."] = "X: Karte verschieben. Für Fähigkeiten die Fokustaste des Spiels nutzen.",
    ["Xbox Series controller"] = "Xbox-Series-Controller",
    ["You are here"] = "Du bist hier",
    ["You are not in a group."] = "Du bist in keiner Gruppe.",
    ["You can still write in the comments on WalkMap's CurseForge page."] = "Du kannst weiterhin in die Kommentare auf WalkMaps CurseForge-Seite schreiben.",
    ["You can't share a quest in combat."] = "Im Kampf kannst du keine Quest teilen.",
    ["You switched the game to its controller interface. Reload so WalkMap's map works with the controller. Until then the map behaves as with mouse and keyboard."] = "Du hast das Spiel auf die Controller-Oberfläche umgestellt. Lade neu, damit WalkMaps Karte mit dem Controller funktioniert. Bis dahin verhält sie sich wie mit Maus und Tastatur.",
    ["You switched the game to its mouse and keyboard interface. Reload so WalkMap's map can also be moved, resized and set up during combat."] = "Du hast das Spiel auf die Maus-und-Tastatur-Oberfläche umgestellt. Lade neu, damit WalkMaps Karte auch im Kampf verschoben, in der Größe geändert und eingestellt werden kann.",
